package com.founderlink.authservice.exception;
import jakarta.servlet.http.HttpServletRequest; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.validation.FieldError; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String> errors=new LinkedHashMap<>();for(FieldError f:e.getBindingResult().getFieldErrors())errors.putIfAbsent(f.getField(),f.getDefaultMessage());return response(HttpStatus.BAD_REQUEST,"Validation failed",r,errors);}@ExceptionHandler(DuplicateEmailException.class) ResponseEntity<ErrorResponse> duplicate(DuplicateEmailException e,HttpServletRequest r){return response(HttpStatus.CONFLICT,e.getMessage(),r,Map.of());}@ExceptionHandler(InvalidCredentialsException.class) ResponseEntity<ErrorResponse> invalidCredentials(InvalidCredentialsException e,HttpServletRequest r){return response(HttpStatus.UNAUTHORIZED,e.getMessage(),r,Map.of());}@ExceptionHandler(BadRequestException.class) ResponseEntity<ErrorResponse> bad(BadRequestException e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,e.getMessage(),r,Map.of());}@ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> unexpected(HttpServletRequest r){return response(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",r,Map.of());}private ResponseEntity<ErrorResponse> response(HttpStatus s,String m,HttpServletRequest r,Map<String,String> fields){return ResponseEntity.status(s).body(new ErrorResponse(Instant.now(),s.value(),m,r.getRequestURI(),fields));} }
